import{_ as a,o as p,c as t,a2 as r}from"./chunks/framework.CqGPl1zp.js";const o="/newx-doc/assets/%E6%94%AF%E4%BB%98%E6%B8%A0%E9%81%93%E9%85%8D%E7%BD%AE.BjItFEQG.png",n="/newx-doc/assets/JSAPI%E6%94%AF%E4%BB%98%E7%9B%AE%E5%BD%95.BE7g0iTq.png",i="/newx-doc/assets/%E6%9B%BF%E6%8D%A2%E5%90%8E%E7%AB%AF%E5%9F%9F%E5%90%8D.DJool5ee.png",c="/newx-doc/assets/%E6%94%B6%E9%93%B6%E5%8F%B0.BOT1BlU9.png",l="/newx-doc/assets/%E7%AB%8B%E5%8D%B3%E6%94%AF%E4%BB%98.DDWrGBcv.png",x=JSON.parse('{"title":"微信公众号支付接入","description":"","frontmatter":{},"headers":[],"relativePath":"pay/wx-pub-pay-demo.md","filePath":"pay/wx-pub-pay-demo.md","lastUpdated":null}'),s={name:"pay/wx-pub-pay-demo.md"};function d(h,e,_,u,m,f){return p(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="微信公众号支付接入" tabindex="-1">微信公众号支付接入 <a class="header-anchor" href="#微信公众号支付接入" aria-label="Permalink to &quot;微信公众号支付接入&quot;">​</a></h1><p>前置阅读：</p><p>① 阅读 <a href="./build">《支付功能开启》</a> 和 <a href="./alipay-pay-demo">《支付宝支付接入》</a> 文档，一定要先跑通支付宝支付流程！！！不跑通支付宝，微信公众号支付更跑不通。</p><p>② 阅读 <a href="./../member/weixin-mp-login">《微信公众号登录》</a> 文档，因为微信公众号支付需要先微信公众号登录，超级麻烦的说！</p><p>注意，微信公众号支付不能使用“测试公众号”，必须使用认证过的公众号。并且，在阅读《公众号登录》文档时，前端项目需要使用 <a href="./../natapp">《内网穿透》</a>，因为微信公众号支付只能在手机微信上测试！！！</p><p>微信公众号支付，使用 WxPubPayClient 客户端进行对接。</p><p>下面，我们以 <code>yudao-mall-uniapp</code> 商城项目，演示微信公众号支付的接入流程。</p><p>友情提示：</p><ul><li><a href="http://niubi.natapp1.cc" target="_blank" rel="noreferrer">http://niubi.natapp1.cc</a> 域名，是我前端项目的访问域名</li><li><a href="http://yunai.natapp1.cc" target="_blank" rel="noreferrer">http://yunai.natapp1.cc</a> 域名，是我后端项目的访问域名</li></ul><p>所以，你的前后端项目也要分别使用 <a href="./../natapp">《内网穿透》</a> 实现独立域名！！！</p><h2 id="_1-第一步-配置支付渠道" tabindex="-1">1. 第一步，配置支付渠道 <a class="header-anchor" href="#_1-第一步-配置支付渠道" aria-label="Permalink to &quot;1. 第一步，配置支付渠道&quot;">​</a></h2><p>① 访问 [支付管理 -&gt; 应用信息] 菜单，点击“商城应用”对应的【微信 JSAPI 支付】，进入支付渠道的配置。如下图所示：</p><p><img src="'+o+'" alt="支付渠道配置"></p><ul><li>在 <a href="https://pay.weixin.qq.com/index.php/core/account/info" target="_blank" rel="noreferrer">https://pay.weixin.qq.com/index.php/core/account/info</a> 地址，可获取微信支付商户号</li><li>在 <a href="https://pay.weixin.qq.com/index.php/core/cert/api_cert#/" target="_blank" rel="noreferrer">https://pay.weixin.qq.com/index.php/core/cert/api_cert#/</a> 地址，可获取 API 证书、密钥</li></ul><p>友情提示：</p><p>可以简单阅读下 <a href="https://pay.weixin.qq.com/doc/v3/partner/4012069852" target="_blank" rel="noreferrer">《微信官方文档 —— JSAPI 支付的接入前准备》</a> 文章。</p><p>目前建议使用微信支付的 V3 版本，并且使用<a href="https://pay.weixin.qq.com/doc/v3/merchant/4012153196" target="_blank" rel="noreferrer">“微信支付公钥”</a> ！！！</p><p>如果使用 V2 版本，最好参考 <a href="https://gitee.com/zhijiantianya/yudao-cloud/issues/ICY1MT" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/yudao-cloud/issues/ICY1MT</a> 帖子，降低 <code>weixin-java</code> 组件的版本。</p><p>② 访问微信支付的 <a href="https://pay.weixin.qq.com/index.php/extend/pay_setting" target="_blank" rel="noreferrer">开发配置</a> 地址，设置 JSAPI 支付目录，设置为前端项目的访问域名。如下图所示：</p><p><img src="'+n+'" alt="JSAPI 支付目录"></p><h2 id="_2-支付功能测试" tabindex="-1">2. 支付功能测试 <a class="header-anchor" href="#_2-支付功能测试" aria-label="Permalink to &quot;2. 支付功能测试&quot;">​</a></h2><p>① IDEA 打开前端 uniapp 项目，修改 <code>.env</code> 配置文件的 <code>SHOPRO_DEV_BASE_URL</code> 配置项目，替换成你的后端项目的访问域名。例如说下图：</p><p><img src="'+i+'" alt="替换后端域名"></p><p>② 使用手机微信，访问前端项目的域名。随便找个商品下单，一路往下走，可以进入“收银台”界面（对应前端项目的 <code>pages/pay/index.vue</code> 文件）。如下图所示：</p><p><img src="'+c+'" alt="收银台"></p><p>③ 选择“微信支付”，点击“立即支付”按钮，即可进行微信支付。如下图所示：</p><p><img src="'+l+'" alt="立即支付"></p><ul><li>前端代码的实现，可见 <code>sheep/platform/pay.js</code> 文件的 <code>#wechatOfficialAccountPay(...)</code> 方法</li><li>后端代码的实现，可见 AppPayOrderController 提供的 <code>#submitPayOrder(...)</code> 接口</li></ul><p>④ 支付成功后，跳转到“支付结果”界面（对应前端项目的 <code>pages/pay/result.vue</code> 文件）。</p><p>友情提示：</p><p>如果这个过程中碰到问题，可以先使用「微信开发者工具」访问前端项目的域名，看看这个过程中有没什么报错。</p><p>自查 30-60 分钟，如果还是无法解决，可以在星球发帖求助！但是注意，一定要先自查，因为这玩意没环境现场，很难搞啊！！！</p>',32)])])}const y=a(s,[["render",d]]);export{x as __pageData,y as default};
